{
  "diagnosis": {
    "overallScore": 72,
    "dimensionScores": [
      {
        "dimension": "JD硬性条件匹配",
        "score": 88,
        "comment": "本科在读，信息管理专业与产品、数据方向有一定相关性，符合校招实习生身份；JD不要求商业项目经验，硬性门槛基本满足。"
      },
      {
        "dimension": "核心职责与项目证据",
        "score": 68,
        "comment": "有原型设计、需求整理、问卷与数据整理、团队协作等课程或校园证据，但缺少教师工具场景和直接用户访谈证据。"
      },
      {
        "dimension": "成果与证据强度",
        "score": 55,
        "comment": "项目多为课程原型或个人练习，未上线，个人贡献有简述但缺少交付结果、量化影响和用户验证反馈。"
      },
      {
        "dimension": "JD关键词与专业能力覆盖",
        "score": 70,
        "comment": "覆盖Figma、需求、Excel、SQL、协作、提示词调试等关键词，但用户访谈、数据分析闭环和产品指标证据不足。"
      },
      {
        "dimension": "表达质量与信息结构",
        "score": 72,
        "comment": "时间倒序清晰，角色与负责事项可读，但描述偏简略，缺少个人贡献边界、结果数据和与目标岗位的对应说明。"
      }
    ],
    "mainIssues": [
      "缺少面向教师工具的用户访谈和需求分析直接证据。",
      "项目成果多为课程原型或个人练习，未上线且缺少量化结果与验证反馈。",
      "数据分析经历偏基础，缺少从数据发现到产品建议的闭环说明。",
      "个人贡献描述有角色标签，但具体行动、产出边界和协作分工不够具体。",
      "教育科技行业理解和AI工具应用深度缺少展开，关键词与JD匹配度可进一步提升。"
    ],
    "prioritySuggestions": [
      "在校园问答Demo中补充试用或访谈对象、问题提纲、关键发现及据此调整需求的过程，若未做正式访谈不要写成用户访谈。",
      "用“目标-我的行动-交付物-结果/反馈”结构改写每段项目，明确个人贡献和团队协作边界。",
      "将食堂满意度调研和学习数据看板改写成“数据发现问题-提出建议-结果”的分析闭环。",
      "补充Figma原型的页面数、核心流程、评审反馈和迭代点，强调原型设计能力，不写成上线产品。",
      "补充AI工具名称、提示词调试目标及效果，说明如何辅助需求整理或原型设计。",
      "按JD顺序重组技能和项目关键词：用户访谈、需求整理、原型设计、数据分析、团队协作、AI工具。"
    ]
  },
  "matchItems": [
    {
      "jdRequirement": "面向在校本科生，可校招实习",
      "resumeEvidence": "金陵信息大学信息管理本科在读，2023.09—2027.06。",
      "evidenceStrength": "strong",
      "needsSupplement": false,
      "optimizationSuggestion": "保留学历信息，补充可实习时间、每周到岗天数和可实习时长，便于招聘方判断。"
    },
    {
      "jdRequirement": "协助教师工具的用户访谈",
      "resumeEvidence": "校园问答Demo中用公开校园资料制作问答原型，并邀请同学试用；未说明是否开展正式访谈、访谈对象和访谈记录。",
      "evidenceStrength": "weak",
      "needsSupplement": true,
      "optimizationSuggestion": "如实际做过访谈或试用，补充访谈人数、问题提纲、关键发现和据此调整的需求；若未访谈，不要写成用户访谈，可改为试用反馈收集。"
    },
    {
      "jdRequirement": "需求整理",
      "resumeEvidence": "校园问答Demo负责需求与提示词调试；图书预约原型整理预约流程；二手书小程序设计负责发布信息页面与交易状态流程原型设计。",
      "evidenceStrength": "moderate",
      "needsSupplement": true,
      "optimizationSuggestion": "用“收集-分类-优先级-原型验证”说明需求整理过程，并补充需求文档、用户故事或流程图等交付物。"
    },
    {
      "jdRequirement": "原型设计",
      "resumeEvidence": "图书预约原型用Figma制作并完成课程展示；二手书小程序设计负责页面与交易状态流程原型，未开发上线。",
      "evidenceStrength": "moderate",
      "needsSupplement": true,
      "optimizationSuggestion": "补充原型工具、页面数量、核心流程、评审反馈和迭代点，突出Figma交互原型能力，避免写成商业上线项目。"
    },
    {
      "jdRequirement": "数据分析",
      "resumeEvidence": "食堂满意度调研参与问卷设计，用Excel整理数据并提交报告；学习数据看板用公开模拟数据练习SQL查询，不代表真实用户行为。",
      "evidenceStrength": "moderate",
      "needsSupplement": true,
      "optimizationSuggestion": "补充样本量、分析维度、关键结论、建议及对活动或产品的启发；学习看板注明模拟数据边界，突出SQL与指标设计能力。"
    },
    {
      "jdRequirement": "有团队协作经验",
      "resumeEvidence": "多个课程项目中担任负责人或成员；校读书协会活动干事，组织读书分享会，协调场地和报名。",
      "evidenceStrength": "strong",
      "needsSupplement": false,
      "optimizationSuggestion": "补充协作规模、分工接口、协调难点和推进结果，突出与同学、设计或其他角色的配合。"
    },
    {
      "jdRequirement": "逻辑清晰，能说明个人贡献",
      "resumeEvidence": "每段经历标注角色和负责事项，但描述较简略，缺少个人贡献边界、决策依据和结果。",
      "evidenceStrength": "weak",
      "needsSupplement": true,
      "optimizationSuggestion": "统一用“目标-我的行动-产出-结果/反馈”结构改写，明确哪些是个人完成、哪些是团队协作。"
    },
    {
      "jdRequirement": "了解AI工具加分",
      "resumeEvidence": "校园问答Demo负责提示词调试；技能栏写有“提示词调试”，但未说明AI工具名称、使用场景和效果。",
      "evidenceStrength": "moderate",
      "needsSupplement": true,
      "optimizationSuggestion": "补充使用的AI工具、提示词调试目标、对比效果，以及如何用AI辅助需求整理或原型设计，不要夸大AI能力。"
    }
  ]
}
